/// Lookup a sound event by id.
pub fn event(id: &str) -> Option<&'static SoundEventDef> {
    SOUND_EVENTS.binary_search_by_key(&id, |e| e.id).ok().map(|i| &SOUND_EVENTS[i])
}

/// Files of an event.
pub fn files(e: &'static SoundEventDef) -> &'static [SoundFileDef] {
    &SOUND_FILES[e.first..e.first + e.len]
}
